window.RP_SESSION={"id":"S-180052eafb36","messages":[{"id":"RP-0242289","time":"2026-08-20T03:13:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"시간이 얼마나 지난 건지, 정신을 어느 정도 차려보니 구멍이나 피가 나던 손은 회복되어 있었다. 그러지 않아도 상관은 없었을 텐데.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242290","time":"2026-08-20T03:13:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"오늘, 내가 뭘 한 거지.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242291","time":"2026-08-20T03:13:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"부모님이 주신 도끼도 잃어버리고, 아니... 버린 건가.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242292","time":"2026-08-20T03:16:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"사람을 죽였다. 죽이지 않으려던 건 아녔다. 애초에, 델타인을 살려야 했으니. 죄책감은 잘 모르겠다. 희생이었다는 생각이 들기도 한다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242293","time":"2026-08-20T03:17:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"…내가 지금 무슨 생각을 하는 거지. 희생? 희생. 진정한 희생은 그곳에서 내가 대신 죽는 거 아녔을까.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242294","time":"2026-08-20T03:17:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"상처라도 남았으면, 난 그 상처를 명예로운 상처라 여겼을까. 아니면 수치라고 생각했을까.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242295","time":"2026-08-20T03:18:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"단검으로 살점 특유의 말랑함을 찌르던 것이 아직도 생생하게 느껴진다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242296","time":"2026-08-20T03:19:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"그래, 그래. 그건 그냥 어쩔 수 없었다고 하자. 그렇게 해버리자.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242297","time":"2026-08-20T03:20:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"그럼 델타인이 죽을 뻔한 건 어떻게 할 건데? 바보같이. 정말, 정말 바보같이.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242298","time":"2026-08-20T03:21:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"정말, 지독하게 이기적이구나. 나라는 사람은. 가족들을 등지고, 동료를 잃을 뻔하고, 사람을 죽이고.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242299","time":"2026-08-20T03:21:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"정말… 역겨운 사람이다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242300","time":"2026-08-20T03:22:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"등이 가볍다. 그것이, 정말 홀로 남겨진 기분을 준다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242301","time":"2026-08-20T03:22:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"죽이지 않으면, 죽을 수밖에 없다는 이 현실에 홀로 남겨진 기분을 준다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242302","time":"2026-08-20T03:23:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"아무것도 남지 않아서, 더 외로웠다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242303","time":"2026-08-20T03:23:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"눈을 감고 생각한다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242304","time":"2026-08-20T03:24:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-c93f55c91873"]},{"id":"RP-0242305","time":"2026-08-20T03:24:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 민첩 판정 :\n[9] + [0] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0242306","time":"2026-08-20T03:24:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"사사삭.","characters":["P-c93f55c91873"]},{"id":"RP-0242307","time":"2026-08-20T03:25:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-c93f55c91873"]},{"id":"RP-0242308","time":"2026-08-20T03:25:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-c93f55c91873"]},{"id":"RP-0242309","time":"2026-08-20T03:25:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"부둣가에 앉아있는 엘레나에게 접근합니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242310","time":"2026-08-20T03:26:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"놀래키지 않게…….\n\n\"엘레나 누나…?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242311","time":"2026-08-20T03:27:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"잠시 대답이 없다, 느릿하게 고개를 돌려 바라봅니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242312","time":"2026-08-20T03:27:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…응, 델타인.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242313","time":"2026-08-20T03:27:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인이 무언가 천에 둘러싸인 걸 내밀었습니다. 그제 만들었던 엠파나다입니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242314","time":"2026-08-20T03:28:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"이거요, 저녁도 안 드셨잖아요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242315","time":"2026-08-20T03:29:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"받아 들고서, 천을 펼쳐보더니 희미하게 웃습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242316","time":"2026-08-20T03:29:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"팩토리 누님 첫 훈련이 끝났어요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242317","time":"2026-08-20T03:29:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…그래? 그렇구나.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242318","time":"2026-08-20T03:29:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…안 먹고 싶다고 하면, 화낼 거야?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242319","time":"2026-08-20T03:30:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"엥, 아뇨. 그럴 수도 있죠.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242320","time":"2026-08-20T03:30:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"뭣 때문에 그러세요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242321","time":"2026-08-20T03:30:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…뭐부터 얘기해야 할까.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242322","time":"2026-08-20T03:31:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"무엇부터 얘기해야, 네가 이해할까.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242323","time":"2026-08-20T03:32:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"길어도 해주세요. 전 누나 이야기 듣는 거 좋더라고요.\"\n\n델타인이 엘레나 옆에 앉습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242324","time":"2026-08-20T03:32:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…네가 죽을 뻔했어. 내가 등신같이 대처해서.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242325","time":"2026-08-20T03:32:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"앗, 차거. 다리가 길어서 신발이 물에 젖었네요.","characters":["P-c93f55c91873"]},{"id":"RP-0242326","time":"2026-08-20T03:33:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"네? 그랬어요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242327","time":"2026-08-20T03:33:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"절 살려주셨다고 들었는데!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242328","time":"2026-08-20T03:33:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…응. 내가 널 죽일 뻔했어.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242329","time":"2026-08-20T03:34:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"험, 저 죽이시려고 하셨어요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242330","time":"2026-08-20T03:34:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"전 굳이 죽어야 한다면 엘레나 누나한테 죽는 게 차라리 좋을 것 같기두 하고.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242331","time":"2026-08-20T03:34:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…내 손에 죽는 게 차라리 좋다니.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242332","time":"2026-08-20T03:35:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"너도, 정말 참 이상한 애야.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242333","time":"2026-08-20T03:35:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"내가, 오늘 얼마나 무서웠는데.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242334","time":"2026-08-20T03:35:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"너 때문에, 미칠 것만 같았어.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242335","time":"2026-08-20T03:35:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"내가 무슨 짓을 해도, 네가 깨어나지 않아서.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242336","time":"2026-08-20T03:37:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어, 엄, 음. 죄송해요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242337","time":"2026-08-20T03:37:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"뒷목을 습관적으로 벅벅 긁었습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242338","time":"2026-08-20T03:37:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"하지만… 전 누나한테 감사하러 온 거예요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242339","time":"2026-08-20T03:38:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…난 네게 그런 걸 받을 정도로 잘난 사람이 아니야.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242340","time":"2026-08-20T03:38:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"차라리 라리에나에게 고마워해.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242341","time":"2026-08-20T03:39:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"그분 아녔으면, 우리 둘 다 죽었어.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242342","time":"2026-08-20T03:39:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"음, 아녜요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242343","time":"2026-08-20T03:40:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"고맙습니다, 엘레나 누나.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242344","time":"2026-08-20T03:40:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-c93f55c91873"]},{"id":"RP-0242345","time":"2026-08-20T03:40:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"눈을 맞추는 게 예의랬지. 델타인이 눈을 치켜뜨며 꾸벅 고개를 숙입니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242346","time":"2026-08-20T03:41:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…하지 마.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242347","time":"2026-08-20T03:41:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"대가리 원위치.\n\n\"험, 왜요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242348","time":"2026-08-20T03:41:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"너 때문에, 정말 짜증 나.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242349","time":"2026-08-20T03:42:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"험.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242350","time":"2026-08-20T03:42:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"…사과는 해도 되나요…?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242351","time":"2026-08-20T03:42:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"너는, 너는 왜 자꾸 그러는 거야.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242352","time":"2026-08-20T03:42:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"내가 오늘 뭘 한 줄 알아?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242353","time":"2026-08-20T03:43:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"사람을 죽였어.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242354","time":"2026-08-20T03:43:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"모, 몰라용… 아, 아하?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242355","time":"2026-08-20T03:43:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"단검을 입 안에 박아넣어서, 그렇게 죽였어.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242356","time":"2026-08-20T03:43:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"사람을, 사람을 죽였다고.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242357","time":"2026-08-20T03:43:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"널 살린다고. 널 살리려고!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242358","time":"2026-08-20T03:44:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…이게, 다…\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242359","time":"2026-08-20T03:44:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아, 어, 어….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242360","time":"2026-08-20T03:44:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"차마 말을 잇지 못했다. 두 손으로 얼굴을 가리고서 고개를 숙였다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242361","time":"2026-08-20T03:44:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…내, 도끼도 버렸단 말이야.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242362","time":"2026-08-20T03:44:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인은 엘레나를 껴안았습니다. 션 씨가 이렇게 남들을 위로하는 걸 본 적이 있걸랑요.","characters":["P-c93f55c91873"]},{"id":"RP-0242363","time":"2026-08-20T03:45:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"부모님이, 부모님이… 내 가족이…\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242364","time":"2026-08-20T03:45:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"그녀의 눈에서 눈물이 새어 나와, 그저 고개를 더 숙입니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242365","time":"2026-08-20T03:46:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"어깨가 젖어들어가는 감각에 입만 벙긋거립니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242366","time":"2026-08-20T03:46:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"험… 엘레나 누나.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242367","time":"2026-08-20T03:46:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"사람을 죽이신 게… 슬프신 거예요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242368","time":"2026-08-20T03:46:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…내 신념이었어.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242369","time":"2026-08-20T03:47:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"사람을, 돕겠다고….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242370","time":"2026-08-20T03:47:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"근데, 전부 다 잃었어.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242371","time":"2026-08-20T03:48:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"음, 어, 제가 위로는 못하지만요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242372","time":"2026-08-20T03:48:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"엘레나 누나는 절 도우시려다 그러신 거잖아요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242373","time":"2026-08-20T03:50:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아무도 누나한테 뭐라 안할 거라구요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242374","time":"2026-08-20T03:50:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"내가 대신 찔려 죽는다는 선택지도 있었지.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242375","time":"2026-08-20T03:50:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"네에? 그게 무슨!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242376","time":"2026-08-20T03:50:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"분명, 분명 더 평화로운 방법이 있었을 거야. 그런데, 그런데.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242377","time":"2026-08-20T03:51:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"내가 병신이라 그래. 불행을 불러와서, 나 때문이야.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242378","time":"2026-08-20T03:51:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"누나!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242379","time":"2026-08-20T03:51:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"부모님을 져버렸어. 내, 내 도끼….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242380","time":"2026-08-20T03:51:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아휴, 참. 엘레나 누나!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242381","time":"2026-08-20T03:52:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"작게 흠칫하고, 고개를 듭니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242382","time":"2026-08-20T03:52:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"왜 그렇게 생각하세요? 이해가 잘 안 가요. 누나 부모님을 생각하세요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242383","time":"2026-08-20T03:53:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"부모는 자식이 죽거나 다치면 슬퍼하잖아요? 뭐, 저희 부모님은 안 그랬지만.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242384","time":"2026-08-20T03:53:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"누나가 그런 생각 하시는 걸 알면 도끼를 잃어버린 것보다 백 배는 슬퍼하실 걸요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242385","time":"2026-08-20T03:54:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"그녀의 눈에 눈물이 가득 고이더니, 그를 올려다봅니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242386","time":"2026-08-20T03:55:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그리고요. 저도 슬퍼요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242387","time":"2026-08-20T03:55:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아니, 이게 슬픈 거 맞나?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242388","time":"2026-08-20T03:55:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아이씨, 모르겠네.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242389","time":"2026-08-20T03:55:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"전 바보라서 이게 화나는 건지 뭔지 잘 모르지만, 누나가 안 죽고 안 다치면 좋겠다구요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242390","time":"2026-08-20T03:55:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그런 생각 하시는 것도 기분이 꽝이에요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242391","time":"2026-08-20T03:55:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…그치만, 도끼를 보면서 항상, 항상… 가족을 생각했단 말이야. 난 이제 뭘 봐야 해…?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242392","time":"2026-08-20T03:56:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"모, 목표를 잃은 기분이야….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242393","time":"2026-08-20T03:56:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"등이, 등이 너무 가벼워서… 외로워.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242394","time":"2026-08-20T03:58:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"무슨 소리세요. 제가 바로 옆에 있잖아요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242395","time":"2026-08-20T03:59:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…널 보라고?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242396","time":"2026-08-20T03:59:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"그치만, 너는 우리 가족들과 닮은 구석이 하나도 없고….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242397","time":"2026-08-20T04:00:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"하지만 지금 여기 같이 있잖아요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242398","time":"2026-08-20T04:00:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"같은 하늘, 같은 땅에 살고, 같은 공기를 마시고!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242399","time":"2026-08-20T04:00:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그리고 가족, 그까이거! 제가 해드리면 되는 거죠!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242400","time":"2026-08-20T04:01:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…내, 가족 해준다고?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242401","time":"2026-08-20T04:01:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…나, 나 안 미워?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242402","time":"2026-08-20T04:01:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"나, 방금까지 너한테….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242403","time":"2026-08-20T04:01:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"당연히 안 밉죠.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242404","time":"2026-08-20T04:01:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인이 배시시 웃었습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242405","time":"2026-08-20T04:02:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…나, 여전히 좋아해?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242406","time":"2026-08-20T04:02:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"밉지도 않고, 여전히?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242407","time":"2026-08-20T04:02:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인은 고개를 끄덕입니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242408","time":"2026-08-20T04:03:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"냉막한 얼굴이 처음으로 자연스러운 부드러움을 갖습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242409","time":"2026-08-20T04:04:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"하, 힘 빠지는 웃음소리를 내고 잠시 바다를 바라봅니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242410","time":"2026-08-20T04:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"엘레나 누나, 전 아직 바보지만 확실하게 아는 것도 있다구요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242411","time":"2026-08-20T04:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어, 이건 말해도 될까요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242412","time":"2026-08-20T04:04:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…응, 말해줘.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242413","time":"2026-08-20T04:05:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"제가 알려줄게요. 누나한테 죽은 영혼이 어떤 생각을 하고 있는지요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242414","time":"2026-08-20T04:06:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…어? 주, 죽은 영혼?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242415","time":"2026-08-20T04:06:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"화들짝 놀라며 황급히 고개를 홱 돌립니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242416","time":"2026-08-20T04:06:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"추측하는 거죠, 뭐. 어둠대왕이잖아요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242417","time":"2026-08-20T04:06:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…아, 아냐. 아냐, 아냐.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242418","time":"2026-08-20T04:06:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"아냐, 말하지 마.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242419","time":"2026-08-20T04:07:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아마도 놈은 이런 생각을 할 거예요. '이 망할 년!', 죄송해요. '아, 존나 아파. 해적질 관둘걸!'\"","characters":["P-c93f55c91873"]},{"id":"RP-0242420","time":"2026-08-20T04:07:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그치만!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242421","time":"2026-08-20T04:07:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인은 엘레나의 구불거리는 머리칼 속으로 손을 넣어 얼굴을 턱 붙잡았습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242422","time":"2026-08-20T04:07:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"누나가 구해준 저도, 누나의 가족도, 우리 길드 동료들도 할 말이 있다고요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242423","time":"2026-08-20T04:08:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"'와, 이건 거의 하늘이 도왔는데?' 나 '이런 든든한 동료가 내 목숨를 구해주다니!'\"","characters":["P-c93f55c91873"]},{"id":"RP-0242424","time":"2026-08-20T04:08:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"'다행히 아직 내 편이 존재하는구나. 나를 위해 사람 죽이는 내 편이란 게 있는 거구나.'\"","characters":["P-c93f55c91873"]},{"id":"RP-0242425","time":"2026-08-20T04:09:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"사제 놈들이 그래요. 나쁜 일엔 업이 따르고, 선한 일엔 그 보답이 따른다고.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242426","time":"2026-08-20T04:10:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"더 좋은 방도가 있었든 아니든, 누나가 아니었으면 전 죽었을 거라구요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242427","time":"2026-08-20T04:10:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"누나는 방관하고 도망칠 수도 있었는데 위험을 무릅쓰고 절 도우시기로 한 거고요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242428","time":"2026-08-20T04:10:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그리고 전 이렇게 생각해요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242429","time":"2026-08-20T04:10:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"이렇게 착한 사람은 오래오래 살면 좋겠다, 라고.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242430","time":"2026-08-20T04:11:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"이렇게나 귀엽고 당찬, 훌륭한 여자와 어울리는 사람은 역시, 나 어둠대왕. 델타인 페트로비치 바그로프 뿐일 거라고.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242431","time":"2026-08-20T04:12:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"황당함이란 감정에 정신이 들었고, 죄책감에 다시 정신을 잃다, 황당함에 또 정신이 들었다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242432","time":"2026-08-20T04:12:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"결국, 작게 웃음이 터져 나왔다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242433","time":"2026-08-20T04:12:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"하, 하하….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242434","time":"2026-08-20T04:13:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…너, 진짜 이상한 거 알아?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242435","time":"2026-08-20T04:13:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"험… 네. 저 그런 소리 많이 들어요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242436","time":"2026-08-20T04:13:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"근데 전 잘 모르겠단 말이죠….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242437","time":"2026-08-20T04:14:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"너 이상해. 엄청 많이.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242438","time":"2026-08-20T04:14:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…그래서, 좋은 거 같아.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242439","time":"2026-08-20T04:14:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"나중에, 정말로 내 가족이 되어줘.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242440","time":"2026-08-20T04:14:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"네가 먼저 해준다고 했잖아. 약속 지켜야 해. 알았지?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242441","time":"2026-08-20T04:14:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"물론이죠.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242442","time":"2026-08-20T04:15:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"엘레나 누나가 상처 입으셨다면, 낮에 한 것처럼 치료해드릴게요. 누나도 또 다친 제 손가락을 치료해주셨으니까.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242443","time":"2026-08-20T04:16:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"마음이 아프시면, 음, 제가 잘 못 알아차릴 수도 있지만 최선을 다해 위로해드릴게요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242444","time":"2026-08-20T04:16:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"그래, 좋아.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242445","time":"2026-08-20T04:16:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"그녀는 옅게 웃더니, 잠시 생각에 잠기다…","characters":["P-89d5e8c6329e"]},{"id":"RP-0242446","time":"2026-08-20T04:17:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…너, 오늘 나랑 뽀뽀한 거 알아?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242447","time":"2026-08-20T04:17:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"바보.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242448","time":"2026-08-20T04:18:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"…네?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242449","time":"2026-08-20T04:18:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"네에에?!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242450","time":"2026-08-20T04:18:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"네에에엣!?!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242451","time":"2026-08-20T04:18:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"부둣가가 떠나가라 고래고래 소리칩니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242452","time":"2026-08-20T04:18:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"생각보다 더 놀라네….","characters":["P-89d5e8c6329e"]},{"id":"RP-0242453","time":"2026-08-20T04:18:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어, 언제요? 제가요? 왜 전 몰랐지?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242454","time":"2026-08-20T04:19:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…그야, 너 기절했을 때 했으니까.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242455","time":"2026-08-20T04:19:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"험…….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242456","time":"2026-08-20T04:19:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아, 아쉽다….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242457","time":"2026-08-20T04:19:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"아, 아쉬? 아쉽다고?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242458","time":"2026-08-20T04:20:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"마른세수 벅벅...","characters":["P-89d5e8c6329e"]},{"id":"RP-0242459","time":"2026-08-20T04:20:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…널 어쩜 좋지.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242460","time":"2026-08-20T04:21:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아니, 그…….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242461","time":"2026-08-20T04:22:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"엘레나 누나랑 뽀뽀했는데, 전 알기는커녕 느낌도 못 느꼈고…….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242462","time":"2026-08-20T04:22:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-c93f55c91873"]},{"id":"RP-0242463","time":"2026-08-20T04:23:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"변태인지, 궁금해서 이러는 건지.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242464","time":"2026-08-20T04:23:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…그, 그렇구나.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242465","time":"2026-08-20T04:24:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"미, 미리 얘기하지만 진짜 뽀뽀 아녔어! 그, 그냥 입술만 닿은 거야.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242466","time":"2026-08-20T04:24:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아, 어, 헉.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242467","time":"2026-08-20T04:24:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"험.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242468","time":"2026-08-20T04:24:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"네.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242469","time":"2026-08-20T04:24:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그럼, 그…….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242470","time":"2026-08-20T04:25:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…그, 뭐?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242471","time":"2026-08-20T04:25:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"…한번만 더, 안되나요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242472","time":"2026-08-20T04:26:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"진정하자, 엘레나. 그냥 입술이 닿으면 어떤 감촉인지 궁금한가 보네….","characters":["P-89d5e8c6329e"]},{"id":"RP-0242473","time":"2026-08-20T04:27:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"심호흡해, 홍당무를 조절하고…","characters":["P-89d5e8c6329e"]},{"id":"RP-0242474","time":"2026-08-20T04:27:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…그래.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242475","time":"2026-08-20T04:27:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"저, 좋아하는 사람이랑 뽀뽀는 처, 어, 음… 네?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242476","time":"2026-08-20T04:28:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"그, 그렇게 얘기하면 이상하잖아!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242477","time":"2026-08-20T04:28:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"그냥 궁금한 거면서, 왜 저렇게 말한담….","characters":["P-89d5e8c6329e"]},{"id":"RP-0242478","time":"2026-08-20T04:28:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어윽, 험, 미, 미안해요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242479","time":"2026-08-20T04:29:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"근데 진짜로, 좋아하는 사람이랑 처음 하는 뽀뽀를 그렇게 넘겨가지고….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242480","time":"2026-08-20T04:29:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"하아….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242481","time":"2026-08-20T04:30:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"어지간히 궁금했나 보네…. 여자 입술이 남자 입술이랑 많이 다르던가?","characters":["P-89d5e8c6329e"]},{"id":"RP-0242482","time":"2026-08-20T04:30:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"델타인의 뺨을 감싸 잡습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242483","time":"2026-08-20T04:30:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"우붑.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242484","time":"2026-08-20T04:31:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"이, 이상한 소리 내지 마! 그, 그냥… 이, 입술만 닿는 거니까.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242485","time":"2026-08-20T04:31:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"작게 움찔하더니, 두 눈 꼭 감고….","characters":["P-89d5e8c6329e"]},{"id":"RP-0242486","time":"2026-08-20T04:32:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"움, 넵.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242487","time":"2026-08-20T04:33:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"…두 사람의 입술이 조심스럽게 닿습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242488","time":"2026-08-20T04:35:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"아랫입술에 전해지는 달콤한 숨결, 그리고 뒤를 잇는 부드럽고 촉촉한 감각에 델타인은 흠칫 놀라고 말았습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242489","time":"2026-08-20T04:36:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"뺨을 감싼 손이 조금 굳어진 것 같다고 생각합니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242490","time":"2026-08-20T04:37:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그리고 델타인은 고개를 좀 더 내려서, 윗입술까지 맞닿을 수 있도록… 입술을 부빕니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242491","time":"2026-08-20T04:38:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"윗입술까지 닿자, 크게 움찔하며 그대로 굳어버립니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242492","time":"2026-08-20T04:39:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"으, 음….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242493","time":"2026-08-20T04:39:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"음.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242494","time":"2026-08-20T04:39:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"얼굴이 급격하게 붉어지더니, 잠시 주저하다 뺨을 조심히 쓰다듬어줍니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242495","time":"2026-08-20T04:40:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"짧은 입맞춤을 끝내고, 입술은 촉촉한 숨결을 코끝에 남긴 채 멀어져갔습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242496","time":"2026-08-20T04:41:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그러나 달빛을 받은 물기 어린 해록색 눈동자가 멱살을 붙들고 있는 것만 같았습니다. 델타인은 눈을 뗄 수가 없었습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242497","time":"2026-08-20T04:41:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"저, 그, 엘레나 누나. 혹, 혹시…… 한번 더….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242498","time":"2026-08-20T04:42:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"델타인의 입술과 눈동자를 번갈아 보다, 이어지는 말에 황급히 입을 틀어막아 밀어냅니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242499","time":"2026-08-20T04:42:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"너, 너…!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242500","time":"2026-08-20T04:42:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"훔, 흠, 흐믐.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242501","time":"2026-08-20T04:42:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"너, 너 변태! 너 뽀뽀 처음 아니지!?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242502","time":"2026-08-20T04:42:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"흐흠흐흐므!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242503","time":"2026-08-20T04:43:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"흐흠흐흠흐!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242504","time":"2026-08-20T04:43:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"떨떠름… 손 떼어냅니다….","characters":["P-89d5e8c6329e"]},{"id":"RP-0242505","time":"2026-08-20T04:43:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"처음 맞아요…!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242506","time":"2026-08-20T04:44:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"거짓말! 안 믿어!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242507","time":"2026-08-20T04:44:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"엑.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242508","time":"2026-08-20T04:44:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"너, 너… 처, 처음인데 어떻게 바로! 입술을 그렇게!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242509","time":"2026-08-20T04:45:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"이, 입술도 부비고! 너…!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242510","time":"2026-08-20T04:45:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아니, 그, 입술 아래쪽만 닿길래….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242511","time":"2026-08-20T04:45:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"다 닿으면 좋겠다고 생각해서….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242512","time":"2026-08-20T04:46:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"험, 죄, 죄송….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242513","time":"2026-08-20T04:46:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이모티콘","characters":["P-c93f55c91873"]},{"id":"RP-0242514","time":"2026-08-20T04:47:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"입술 꾹 깨물다가… 한숨.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242515","time":"2026-08-20T04:47:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"됐어, 너나 나나 모르는 건 비슷한 거 같다는 생각이 들었어.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242516","time":"2026-08-20T04:49:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그러면, 그…….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242517","time":"2026-08-20T04:49:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"저희 그거인가요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242518","time":"2026-08-20T04:50:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…뭐가? 가족?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242519","time":"2026-08-20T04:50:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"그건 나중에 되어달라고 했잖아.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242520","time":"2026-08-20T04:51:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그, 여… 영어, 연운, 연민….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242521","time":"2026-08-20T04:51:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"여, 연인?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242522","time":"2026-08-20T04:53:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…응?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242523","time":"2026-08-20T04:53:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"연인? 여, 연인? 연인…","characters":["P-89d5e8c6329e"]},{"id":"RP-0242524","time":"2026-08-20T04:53:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"네, 넵. 연인…….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242525","time":"2026-08-20T04:53:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"연인이 그러니까, 그, 사랑하는 사람이잖아. 연인?","characters":["P-89d5e8c6329e"]},{"id":"RP-0242526","time":"2026-08-20T04:54:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"여, 연인?","characters":["P-89d5e8c6329e"]},{"id":"RP-0242527","time":"2026-08-20T04:55:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…내가, 널 사랑하나…?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242528","time":"2026-08-20T04:55:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"어, 어? 사랑하나? 그런가?","characters":["P-89d5e8c6329e"]},{"id":"RP-0242529","time":"2026-08-20T04:56:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그, 저 때문에 사람두 죽이셨구…….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242530","time":"2026-08-20T04:56:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"아, 아니, 이 말 하지 말라고 하셨죠. 죄송합니다.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242531","time":"2026-08-20T04:56:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"가슴도 막, 아프시다고.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242532","time":"2026-08-20T04:57:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"아, 어… 어.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242533","time":"2026-08-20T04:58:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"그, 그러면 어? 나는, 그러면… 바, 방금 첫 키스 아냐?! 그러니까, 사랑의 키스? 그, 그런 거잖아!","characters":["P-89d5e8c6329e"]},{"id":"RP-0242534","time":"2026-08-20T04:58:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"얼굴이 급격하게 익어가더니, 벌떡 일어납니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242535","time":"2026-08-20T04:58:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…나, 으. 아! 으, 으악! 나, 나 이만 가볼게!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242536","time":"2026-08-20T04:58:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어, 어!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242537","time":"2026-08-20T04:58:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"엘레나 누나!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242538","time":"2026-08-20T04:59:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"여, 연인인 거죠?! 네-?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242539","time":"2026-08-20T04:59:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"도망쳐, 엘레나! 도망쳐! 첫 키스가 이런 거라니! 상상이랑… 다르잖아!","characters":["P-89d5e8c6329e"]},{"id":"RP-0242540","time":"2026-08-20T04:59:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-89d5e8c6329e"]},{"id":"RP-0242541","time":"2026-08-20T04:59:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'Reggiano Elena'의 민첩 판정 :\n[1] + [0] = [1]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-0242542","time":"2026-08-20T04:59:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"?","characters":["P-89d5e8c6329e"]},{"id":"RP-0242543","time":"2026-08-20T04:59:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"험.","characters":["P-c93f55c91873"]},{"id":"RP-0242544","time":"2026-08-20T04:59:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!어둠 난이도 1","characters":["P-c93f55c91873"]},{"id":"RP-0242545","time":"2026-08-20T04:59:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 어둠 판정 :\n[2, 3, 4] + [3, 5, 6]\n성공수 : [ 3 ]","characters":[]},{"id":"RP-0242546","time":"2026-08-20T05:00:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"수인을 맺어서 촉수 세 다발을 뽑아냅니다.\n\n넘어지려는 엘레나를 캐치!","characters":["P-c93f55c91873"]},{"id":"RP-0242547","time":"2026-08-20T05:00:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"아, 으앗…!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242548","time":"2026-08-20T05:00:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"휴, 조심하세요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242549","time":"2026-08-20T05:00:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"도망치다가 잡히고, 넘어지다가 잡히고. 차마 고개를 들지 못합니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242550","time":"2026-08-20T05:01:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"괜히 옷자락만 꼬옥…","characters":["P-89d5e8c6329e"]},{"id":"RP-0242551","time":"2026-08-20T05:01:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"촉수를 끌어당겨 엘레나를 세우고, 다가옵니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242552","time":"2026-08-20T05:01:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"누나, 안 다치셨어요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242553","time":"2026-08-20T05:02:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…으, 응. 괜찮아….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242554","time":"2026-08-20T05:02:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"도망칠 틈만 보는 중…","characters":["P-89d5e8c6329e"]},{"id":"RP-0242555","time":"2026-08-20T05:03:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"어, 언제 도망가지.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242556","time":"2026-08-20T05:03:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그래서, 그….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242557","time":"2026-08-20T05:03:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"누나, 저희 연인이란 거. 맞나요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242558","time":"2026-08-20T05:03:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"뽀, 뽀뽀도 했는데……!\"","characters":["P-c93f55c91873"]},{"id":"RP-0242559","time":"2026-08-20T05:03:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"으, 으악! 모, 몰라! 몰라!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242560","time":"2026-08-20T05:03:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"내, 내 첫 키스….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242561","time":"2026-08-20T05:04:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"이, 이렇게 첫 키스를 할 줄은 몰랐다고!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242562","time":"2026-08-20T05:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어, 험, 미, 미안요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242563","time":"2026-08-20T05:04:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"몰라, 몰라아…. 나, 나 너 좋아하나? 조, 좋아하는 건가?\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242564","time":"2026-08-20T05:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"어, 네? 아니예요?\"","characters":["P-c93f55c91873"]},{"id":"RP-0242565","time":"2026-08-20T05:04:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"저, 전 좋아하는 사람이랑만 키스하는 건줄 알았는데….\"","characters":["P-c93f55c91873"]},{"id":"RP-0242566","time":"2026-08-20T05:05:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…조, 좋아하는 거 같기도 하고. 아, 아니. 키스는 좋아하는 사람이랑만 하는 거 맞긴 한데!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242567","time":"2026-08-20T05:05:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"결국 다시 두 손으로 얼굴을 가립니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242568","time":"2026-08-20T05:05:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인이 엘레나에게 가까이 붙어서는…","characters":["P-c93f55c91873"]},{"id":"RP-0242569","time":"2026-08-20T05:06:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"엘레나의 손목을 살포시 잡고는 얼굴을 들이밀었습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242570","time":"2026-08-20T05:06:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"그럼, 다시 해볼게요. 해보고 알려주세요.\"","characters":["P-c93f55c91873"]},{"id":"RP-0242571","time":"2026-08-20T05:07:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…너, 너 진짜!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242572","time":"2026-08-20T05:07:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…아, 알았어. 이번엔 좀 진지하게 해볼게….\"","characters":["P-89d5e8c6329e"]},{"id":"RP-0242573","time":"2026-08-20T05:08:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"두 눈 꼬옥… 파들파들…","characters":["P-89d5e8c6329e"]},{"id":"RP-0242574","time":"2026-08-20T05:11:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"풍성한 머리칼에 조막만 한 얼굴. 교차하듯 감긴 기다란 속눈썹과 오똑한 코, 도톰한 입술. 앙증맞은 귀와 새하얀 목, 가녀린 어깨….","characters":["P-c93f55c91873"]},{"id":"RP-0242575","time":"2026-08-20T05:12:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인이 목을 홱 숙여서 달싹이는 입술에 다시 접촉합니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242576","time":"2026-08-20T05:13:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"지금은 분명 여름이지만, 봄의 싱그러움이 입술에 닿은 것 같습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242577","time":"2026-08-20T05:14:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"말리꽃, 또는 사과 향기가 입안에 진동했습니다. 어쩌면, 나중에 이 향기를 맡으면 이 입맞춤을 떠올릴지도 모르겠다, 고 델타인이 생각했습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242578","time":"2026-08-20T05:14:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"미간을 찌푸리는 것처럼 두 눈을 더욱 꾹 감고, 델타인의 옷자락을 황급히 붙잡습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242579","time":"2026-08-20T05:15:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"얼굴이 터질 것만 같이 뜨겁고, 온몸이 겁이라도 먹은 듯이 파들파들 떨려오는 것이… 꼭 소설에서 읽은 것과 같았습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242580","time":"2026-08-20T05:15:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"으음.\"\n\n떨어지려던 입술이 다시 끌려갑니다. 더 깊이, 설육이 델타인의 치아와 잇몸을 간지럽혔습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242581","time":"2026-08-20T05:18:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"숨과 침이 뒤섞이는 소리. 델타인은 어쩌다 제 구강으로 파고든 침입자를 저도 모르게 허용했습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242582","time":"2026-08-20T05:18:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"이게… 운명의 사랑일까?","characters":["P-89d5e8c6329e"]},{"id":"RP-0242583","time":"2026-08-20T05:19:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"어쩐지, 기분이 몽롱해져 델타인의 옷을 붙잡던 손에 힘이 빠져갑니다. 한껏 구기던 미간도 차차 펴지더니, 그녀도 모르게 그에게 조금 더 기대어왔습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242584","time":"2026-08-20T05:20:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"사랑을 찾은 것만 같습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242585","time":"2026-08-20T05:20:00+09:00","room":"RP","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"아주 부드러운 사랑.","characters":["P-89d5e8c6329e"]},{"id":"RP-0242586","time":"2026-08-20T05:22:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"곧은 눈썹, 날렵하게 우뚝 선 콧대, 창백한 피부… 전부 속절없이 연한 장밋빛 열망에 덮혀갔습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242587","time":"2026-08-20T05:25:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"델타인 페트로비치 바그로프. 어릴 때부터 사랑받지 못하고 고생만 했으니, 어찌 남들처럼 되고 싶지 않았을까요? \n\n불우한 시절을 오늘까지 버텨왔으니, 오늘이 그의 가장 좋은 시절일 것이고, 가을이 오고 겨울이 지나도 추억은 영원히 여름이었습니다.","characters":["P-c93f55c91873"]},{"id":"RP-0242588","time":"2026-08-20T05:25:00+09:00","room":"RP","name":"델타인","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c93f55c91873"]},{"id":"RP-0242589","time":"2026-08-20T05:25:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
